static const char *rm_propulsion_names[] = {
    "none",
    "cartridge_low_velocity",
    "rocket_tube_burnout",
    "rocket_clip_tube",
    "two_stage_rpg",
    "boosted_grenade_no_sustainer",
    "generic_rocket"
};

static const char *rm_fin_rule_names[] = {
    "none",
    "spin_stabilized",
    "fixed_ring",
    "fixed_foldout",
    "deploy_after_launch"
};

static const char *rm_trail_rule_names[] = {
    "none",
    "muzzle_puff_only",
    "backblast_only",
    "short_rocket_smoke",
    "delayed_sustainer",
    "coast_minimal"
};

const RM_Mesh *rm_get_mesh(int mesh_id)
{
    if (mesh_id < 0 || mesh_id >= RMESH_COUNT) {
        return (const RM_Mesh *)0;
    }
    return rm_meshes[mesh_id];
}

const char *rm_get_mesh_name(int mesh_id)
{
    const RM_Mesh *m;
    m = rm_get_mesh(mesh_id);
    if (!m) {
        return "";
    }
    return m->name;
}

const RM_EjectHint *rm_get_eject_hint(int projectile_mesh_id)
{
    if (projectile_mesh_id < 0 || projectile_mesh_id >= RMESH_COUNT) {
        return (const RM_EjectHint *)0;
    }
    return &rm_eject_hints[projectile_mesh_id];
}

const RM_BehaviorProfile *rm_get_behavior_profile(int mesh_id)
{
    if (mesh_id < 0 || mesh_id >= RMESH_COUNT) {
        return (const RM_BehaviorProfile *)0;
    }
    return &rm_behavior_profiles[mesh_id];
}

int rm_behavior_is_projectile(int mesh_id)
{
    if (mesh_id < 0 || mesh_id >= RMESH_COUNT) {
        return 0;
    }
    if (rm_behavior_profiles[mesh_id].propulsion_model == RM_PROP_NONE) {
        return 0;
    }
    return 1;
}

const char *rm_get_propulsion_name(int propulsion_model)
{
    if (propulsion_model < 0 || propulsion_model > RM_PROP_GENERIC_ROCKET) {
        return "unknown";
    }
    return rm_propulsion_names[propulsion_model];
}

const char *rm_get_fin_rule_name(int fin_rule)
{
    if (fin_rule < 0 || fin_rule > RM_FIN_DEPLOY_AFTER_LAUNCH) {
        return "unknown";
    }
    return rm_fin_rule_names[fin_rule];
}

const char *rm_get_trail_rule_name(int trail_rule)
{
    if (trail_rule < 0 || trail_rule > RM_TRAIL_COAST_MINIMAL) {
        return "unknown";
    }
    return rm_trail_rule_names[trail_rule];
}
